38:  * renders it and any other consumer reads the same parsed object, so
39:  * findings.json stays one request instead of a second fetch. A failed load
40:  * clears the memo so the next consumer can retry instead of inheriting the
41:  * rejection forever.
42:  */
43: let reportLoad: Promise<FindingsReport> | null = null
44: 
45: export function loadSharedFindingsReport(): Promise<FindingsReport> {
46:   if (!reportLoad) {
